import logging
import time
import os
from functools import partial
from robot.libraries.Remote import Remote
from ta_kiss_core.sshconnection.sshconnection import SshConnection


class BaseRemoteLib(object):
    """basic remote lib"""
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, uri, timeout=None):
        self.__uri = uri
        self._remote = Remote(uri, timeout=timeout)

    def _run_keyword(self, _kw_name, *_args, **_kwargs):
        result = self._remote.run_keyword(_kw_name, _args, _kwargs)
        return result

    def __getattr__(self, name):
        if name not in self._remote.get_keyword_names():
            raise AttributeError("No keyword '%s' in remote lib." % name)
        return partial(self._run_keyword, name)

    def __str__(self):
        return "RemoteLibInstance: %s" % self.__uri


class RemoteLib(object):

    def __init__(self, host_ip):
        logging.debug("to Start library in remote pc {}".format(host_ip))
        self.host_ip = host_ip

    def start_remote_lib(self, lib_name, timeout='50min'):
        """start library in remote pc.

        :param lib_name: remote lib name
        :param timeout: timeout
        """
        self._start_remote_server(lib_name)
        time.sleep(3)
        pid = self._get_started_process_pid()
        logging.debug("{}:{}".format(self.host_ip, pid))
        remote_handle = BaseRemoteLib(uri="{}:{}".format(self.host_ip, pid), timeout=timeout)
        logging.debug("start remote {} library successed.".format(lib_name))
        return remote_handle

    def _start_remote_server(self, lib_name):
        """start remote server
        """
        self._execute_command_by_ssh('sudo iptables -F', self.host_ip)
        server_path = os.path.join(os.path.dirname(__file__), "robotremoteserver.py")
        cmd = "python {} -l {} -i {} -p 0 -s True >/dev/null 2>&1 &".format(server_path, lib_name, self.host_ip)
        self._execute_command_by_ssh(cmd, self.host_ip)

    def _get_started_process_pid(self):
        """get started process pid
        """
        port_file = '/tmp/remote_port.txt'
        ret = self._execute_command_by_ssh("cat %s" % port_file, self.host_ip)
        logging.info("remote_port.txt info:{}".format(ret))
        if ret == '':
            raise Exception("Remote lib start fail.Please check whether library in remote is the same with local.")
        return ret[0]

    def _execute_command_by_ssh(self, command, host_ip):
        """
        """
        ssh_client = SshConnection(host_ip, 'ute', 'ute')
        ret = ''
        try:
            ssh_client._setup()
            logging.info("execute command:{}".format(command))
            ret = ssh_client.execute(command)
        except Exception as e:
            raise Exception("{} execute fail!Detail is {}".format(command, str(e)))
        finally:
            ssh_client._teardown()
            return ret

    def stop_remote_lib(self):
        """stop remote server in remote pc
        """
        kill_cmd = "timeout 10 sudo kill -9 $(ps -ef|grep robotremoteserver.py|\
    grep -v grep|awk '{print $2}') 1>/dev/null 2>&1"
        self._execute_command_by_ssh(kill_cmd, self.host_ip)
